INSERT INTO `cache` VALUES ('laravel-cache-review:v1:product_reviews:1', 'a:2:{s:7:\"reviews\";a:12:{i:0;a:11:{s:8:\"customer\";s:17:\"Đặng Thị Mai\";s:2:\"id\";i:8;s:8:\"initials\";s:2:\"TM\";s:13:\"helpful_count\";i:0;s:6:\"rating\";i:5;s:7:\"content\";s:170:\"Sau sinh 6 tháng mình dùng theo hướng dẫn của shop, bổ máu, da dẻ hồng hào hơn. Tư vấn nhiệt tình qua hotline, gửi cả cách dùng chi tiết.\";s:11:\"is_verified\";b:1;s:10:\"created_at\";s:10:\"13/10/2026\";s:6:\"images\";a:0:{}s:11:\"admin_reply\";N;s:12:\"masked_phone\";s:10:\"097****455\";}i:1;a:11:{s:8:\"customer\";s:14:\"Phạm Thu Hà\";s:2:\"id\";i:6;s:8:\"initials\";s:2:\"TH\";s:13:\"helpful_count\";i:0;s:6:\"rating\";i:5;s:7:\"content\";s:206:\"Chị đồng nghiệp giới thiệu, đặt thử 500g. Củ đều nhau, không thấy vụn trộn bột lạ, hãm nước uống vị đắng nhẹ rồi ngọt hậu. Sẽ mua thêm làm quà biếu.\";s:11:\"is_verified\";b:1;s:10:\"created_at\";s:10:\"08/10/2026\";s:6:\"images\";a:0:{}s:11:\"admin_reply\";N;s:12:\"masked_phone\";s:10:\"093****899\";}i:2;a:11:{s:8:\"customer\";s:18:\"Nguyễn Thị Lan\";s:2:\"id\";i:4;s:8:\"initials\";s:2:\"TL\";s:13:\"helpful_count\";i:0;s:6:\"rating\";i:5;s:7:\"content\";s:196:\"Củ già 3-4 năm, cầm nặng tay, gõ nghe tiếng đanh. Thái lát hầm gà ác nước rất ngọt, hậu ngọt sâu ở cổ họng. Đóng gói túi zip kèm gói hút ẩm kỹ càng.\";s:11:\"is_verified\";b:1;s:10:\"created_at\";s:10:\"07/10/2026\";s:6:\"images\";a:0:{}s:11:\"admin_reply\";N;s:12:\"masked_phone\";s:10:\"098****321\";}i:3;a:11:{s:8:\"customer\";s:13:\"Hoàng Chấn\";s:2:\"id\";i:2;s:8:\"initials\";s:2:\"HC\";s:13:\"helpful_count\";i:1;s:6:\"rating\";i:5;s:7:\"content\";s:44:\"Rất tốt, sản phẩm chuẩn Tây Bắc\";s:11:\"is_verified\";b:1;s:10:\"created_at\";s:10:\"06/10/2026\";s:6:\"images\";a:0:{}s:11:\"admin_reply\";N;s:12:\"masked_phone\";s:10:\"035****324\";}i:4;a:11:{s:8:\"customer\";s:10:\"Nguyen Thu\";s:2:\"id\";i:1;s:8:\"initials\";s:2:\"NT\";s:13:\"helpful_count\";i:2;s:6:\"rating\";i:5;s:7:\"content\";s:89:\"Hương vị rất thơm ngon, đóng gói cẩn thận. Tôi sẽ mua lại lần nữa.\";s:11:\"is_verified\";b:1;s:10:\"created_at\";s:10:\"05/10/2026\";s:6:\"images\";a:0:{}s:11:\"admin_reply\";N;s:12:\"masked_phone\";s:0:\"\";}i:5;a:11:{s:8:\"customer\";s:16:\"Lưu Thanh Trúc\";s:2:\"id\";i:12;s:8:\"initials\";s:2:\"TT\";s:13:\"helpful_count\";i:0;s:6:\"rating\";i:5;s:7:\"content\";s:176:\"Thái lát ngâm mật ong 25 ngày đã dùng được, vị dễ uống, cả nhà đều thích. Đóng gói có túi hút ẩm và hướng dẫn bảo quản in rõ ràng.\";s:11:\"is_verified\";b:1;s:10:\"created_at\";s:10:\"27/09/2026\";s:6:\"images\";a:0:{}s:11:\"admin_reply\";N;s:12:\"masked_phone\";s:10:\"093****766\";}i:6;a:11:{s:8:\"customer\";s:18:\"Hoàng Thị Nhung\";s:2:\"id\";i:10;s:8:\"initials\";s:2:\"TN\";s:13:\"helpful_count\";i:0;s:6:\"rating\";i:5;s:7:\"content\";s:183:\"Nhà có người tai biến nên tôi mua về cho uống cùng thuốc theo chỉ định bác sĩ. Hàng chuẩn, không lẫn tam thất nam, vị đắng đặc trưng rõ rệt.\";s:11:\"is_verified\";b:1;s:10:\"created_at\";s:10:\"20/09/2026\";s:6:\"images\";a:0:{}s:11:\"admin_reply\";N;s:12:\"masked_phone\";s:10:\"091****344\";}i:7;a:11:{s:8:\"customer\";s:17:\"Bùi Đức Toàn\";s:2:\"id\";i:9;s:8:\"initials\";s:3:\"ĐT\";s:13:\"helpful_count\";i:0;s:6:\"rating\";i:5;s:7:\"content\";s:164:\"Mua 1kg loại 24-26 củ/kg ngâm rượu hạ thổ. Củ to đẹp đồng đều, không sâu mọt. Giao hàng đóng thùng carton chống sốc cẩn thận.\";s:11:\"is_verified\";b:1;s:10:\"created_at\";s:10:\"14/09/2026\";s:6:\"images\";a:0:{}s:11:\"admin_reply\";N;s:12:\"masked_phone\";s:10:\"090****677\";}i:8;a:11:{s:8:\"customer\";s:14:\"Ngô Văn Sơn\";s:2:\"id\";i:11;s:8:\"initials\";s:2:\"VS\";s:13:\"helpful_count\";i:0;s:6:\"rating\";i:5;s:7:\"content\";s:178:\"Lần thứ 3 đặt hàng. Bột tán mịn, hũ thủy tinh kín, để ngăn mát dùng dần. Ship nhanh, được freeship vì đơn trên 300k. Điểm 5 sao xứng đáng.\";s:11:\"is_verified\";b:1;s:10:\"created_at\";s:10:\"14/09/2026\";s:6:\"images\";a:0:{}s:11:\"admin_reply\";N;s:12:\"masked_phone\";s:10:\"096****233\";}i:9;a:11:{s:8:\"customer\";s:16:\"Võ Quốc Bảo\";s:2:\"id\";i:7;s:8:\"initials\";s:2:\"QB\";s:13:\"helpful_count\";i:0;s:6:\"rating\";i:5;s:7:\"content\";s:190:\"Giá cao hơn ngoài chợ nhưng chất lượng thì khỏi bàn: không mùi hắc sulphur, ruột xám xanh đúng chuẩn tam thất bắc. Có tem truy xuất nguồn gốc, yên tâm.\";s:11:\"is_verified\";b:1;s:10:\"created_at\";s:10:\"22/08/2026\";s:6:\"images\";a:0:{}s:11:\"admin_reply\";N;s:12:\"masked_phone\";s:10:\"091****566\";}i:10;a:11:{s:8:\"customer\";s:17:\"Lê Văn Cường\";s:2:\"id\";i:5;s:8:\"initials\";s:2:\"VC\";s:13:\"helpful_count\";i:0;s:6:\"rating\";i:5;s:7:\"content\";s:171:\"Mua về tán bột uống mỗi sáng 3g pha mật ong, người khỏe hơn rõ, ngủ sâu giấc. Shop hỗ trợ tán bột miễn phí nhanh gọn. Rất hài lòng.\";s:11:\"is_verified\";b:1;s:10:\"created_at\";s:10:\"21/08/2026\";s:6:\"images\";a:0:{}s:11:\"admin_reply\";N;s:12:\"masked_phone\";s:10:\"090****233\";}i:11;a:11:{s:8:\"customer\";s:17:\"Trần Minh Hải\";s:2:\"id\";i:3;s:8:\"initials\";s:2:\"MH\";s:13:\"helpful_count\";i:0;s:6:\"rating\";i:5;s:7:\"content\";s:175:\"Củ tam thất khô chuẩn, mặt cắt xám ngọc đúng như mô tả, tán bột uống rất dễ. Giao hàng hơi lâu so với hẹn. Nói chung vẫn sẽ mua lại.\";s:11:\"is_verified\";b:1;s:10:\"created_at\";s:10:\"21/08/2026\";s:6:\"images\";a:0:{}s:11:\"admin_reply\";N;s:12:\"masked_phone\";s:10:\"091****127\";}}s:5:\"stats\";a:4:{s:3:\"avg\";d:5;s:7:\"average\";d:5;s:5:\"total\";i:12;s:7:\"by_star\";a:5:{i:5;i:12;i:4;i:0;i:3;i:0;i:2;i:0;i:1;i:0;}}}', 1792036143);
INSERT INTO `cache` VALUES ('laravel-cache-review:v1:product_reviews:2', 'a:2:{s:7:\"reviews\";a:20:{i:0;a:11:{s:8:\"customer\";s:22:\"Mai Thị Hồng Nhung\";s:2:\"id\";i:35;s:8:\"initials\";s:2:\"HN\";s:13:\"helpful_count\";i:0;s:6:\"rating\";i:5;s:7:\"content\";s:184:\"Khách khó tính như mình cũng phải khen: nụ nguyên bông không dập nát, nước trà trong, không cặn. Đã giới thiệu cho hai chị đồng nghiệp cùng đặt.\";s:11:\"is_verified\";b:1;s:10:\"created_at\";s:10:\"14/10/2026\";s:6:\"images\";a:0:{}s:11:\"admin_reply\";N;s:12:\"masked_phone\";s:10:\"093****788\";}i:1;a:11:{s:8:\"customer\";s:21:\"Vương Tuấn Kiệt\";s:2:\"id\";i:34;s:8:\"initials\";s:2:\"TK\";s:13:\"helpful_count\";i:0;s:6:\"rating\";i:5;s:7:\"content\";s:186:\"Đặt hôm qua hôm nay đã nhận hàng, đóng gói 2 lớp túi zip. Pha thử tách đầu tiên: hương dịu, vị đắng nhẹ tan nhanh, ngọt hậu kéo dài. Chuẩn bài.\";s:11:\"is_verified\";b:1;s:10:\"created_at\";s:10:\"13/10/2026\";s:6:\"images\";a:0:{}s:11:\"admin_reply\";N;s:12:\"masked_phone\";s:10:\"097****677\";}i:2;a:11:{s:8:\"customer\";s:16:\"Tô Ánh Tuyết\";s:2:\"id\";i:33;s:8:\"initials\";s:3:\"ÁT\";s:13:\"helpful_count\";i:0;s:6:\"rating\";i:5;s:7:\"content\";s:176:\"Mẹ mình 62 tuổi uống đều mỗi tối, bảo giấc ngủ cải thiện, đêm trở dậy ít hơn. Nụ to đều, không lẫn tạp chất. Cảm ơn shop nhiều.\";s:11:\"is_verified\";b:1;s:10:\"created_at\";s:10:\"11/10/2026\";s:6:\"images\";a:0:{}s:11:\"admin_reply\";N;s:12:\"masked_phone\";s:10:\"091****566\";}i:3;a:11:{s:8:\"customer\";s:16:\"Phan Nhật Hào\";s:2:\"id\";i:32;s:8:\"initials\";s:2:\"NH\";s:13:\"helpful_count\";i:0;s:6:\"rating\";i:5;s:7:\"content\";s:170:\"Giao hàng đóng thùng chống sốc cẩn thận, hạn đóng gói in rõ trên bao bì. Trà hãm xong để nguội uống giải khát mùa nóng cũng rất ổn.\";s:11:\"is_verified\";b:1;s:10:\"created_at\";s:10:\"09/10/2026\";s:6:\"images\";a:0:{}s:11:\"admin_reply\";N;s:12:\"masked_phone\";s:10:\"090****455\";}i:4;a:11:{s:8:\"customer\";s:17:\"Dương Mỹ Linh\";s:2:\"id\";i:31;s:8:\"initials\";s:2:\"ML\";s:13:\"helpful_count\";i:0;s:6:\"rating\";i:5;s:7:\"content\";s:182:\"Mùa hanh khô pha nụ tam thất với mật ong uống rất dễ chịu, họng bớt khô. Giá nhỉnh hơn trà thường nhưng chất lượng xứng đáng, sẽ mua lại.\";s:11:\"is_verified\";b:1;s:10:\"created_at\";s:10:\"06/10/2026\";s:6:\"images\";a:0:{}s:11:\"admin_reply\";N;s:12:\"masked_phone\";s:10:\"096****344\";}i:5;a:11:{s:8:\"customer\";s:7:\"Mai Hoa\";s:2:\"id\";i:37;s:8:\"initials\";s:2:\"MH\";s:13:\"helpful_count\";i:0;s:6:\"rating\";i:4;s:7:\"content\";s:40:\"Chất lượng tốt, hậu ngọt rõ.\";s:11:\"is_verified\";b:1;s:10:\"created_at\";s:10:\"04/10/2026\";s:6:\"images\";a:0:{}s:11:\"admin_reply\";N;s:12:\"masked_phone\";s:10:\"098****900\";}i:6;a:11:{s:8:\"customer\";s:16:\"Hồ Văn Đạt\";s:2:\"id\";i:30;s:8:\"initials\";s:3:\"VĐ\";s:13:\"helpful_count\";i:0;s:6:\"rating\";i:5;s:7:\"content\";s:168:\"Kiểm hàng trước khi thanh toán, mở ra xem kỹ: nụ tím xám tự nhiên đúng mô tả, không non ép. 500g dùng được hơn tháng cho 2 vợ chồng.\";s:11:\"is_verified\";b:1;s:10:\"created_at\";s:10:\"02/10/2026\";s:6:\"images\";a:0:{}s:11:\"admin_reply\";N;s:12:\"masked_phone\";s:10:\"098****233\";}i:7;a:11:{s:8:\"customer\";s:20:\"Đỗ Hoài Thương\";s:2:\"id\";i:29;s:8:\"initials\";s:2:\"HT\";s:13:\"helpful_count\";i:0;s:6:\"rating\";i:5;s:7:\"content\";s:181:\"Nhân viên trực đêm nên mua về pha trà thay cà phê. Tỉnh táo mà không bị hồi hộp, sáng ngủ lại dễ. Nụ khô sạch, không thấy bụi hay vụn lạ.\";s:11:\"is_verified\";b:1;s:10:\"created_at\";s:10:\"29/09/2026\";s:6:\"images\";a:0:{}s:11:\"admin_reply\";N;s:12:\"masked_phone\";s:10:\"091****122\";}i:8;a:11:{s:8:\"customer\";s:26:\"Trịnh Thị Lan Phương\";s:2:\"id\";i:28;s:8:\"initials\";s:2:\"LP\";s:13:\"helpful_count\";i:0;s:6:\"rating\";i:5;s:7:\"content\";s:186:\"Sau sinh 8 tháng mình uống trà nụ tam thất theo hướng dẫn của shop, người ấm áp hơn, sữa cũng đều hơn. Vị hơi đắng đầu lưỡi nhưng hậu ngọt.\";s:11:\"is_verified\";b:1;s:10:\"created_at\";s:10:\"25/09/2026\";s:6:\"images\";a:0:{}s:11:\"admin_reply\";N;s:12:\"masked_phone\";s:10:\"090****011\";}i:9;a:11:{s:8:\"customer\";s:14:\"Lưu Quang Vũ\";s:2:\"id\";i:27;s:8:\"initials\";s:2:\"QV\";s:13:\"helpful_count\";i:0;s:6:\"rating\";i:5;s:7:\"content\";s:163:\"Mình mua combo nụ + củ tam thất. Nụ hãm trà, củ tán bột uống riêng. Shop gói kèm hướng dẫn sử dụng in rõ ràng, tỉ mỉ chu đáo.\";s:11:\"is_verified\";b:1;s:10:\"created_at\";s:10:\"21/09/2026\";s:6:\"images\";a:0:{}s:11:\"admin_reply\";N;s:12:\"masked_phone\";s:10:\"093****900\";}i:10;a:11:{s:8:\"customer\";s:22:\"Ngô Thị Hải Yến\";s:2:\"id\";i:26;s:8:\"initials\";s:2:\"HY\";s:13:\"helpful_count\";i:0;s:6:\"rating\";i:5;s:7:\"content\";s:190:\"So với chỗ cũ mình từng mua thì nụ ở đây đều và đẹp hơn hẳn, ít nụ nở gãy. Pha ra nước màu vàng óng rất đẹp. Được freeship vì đơn trên 300k.\";s:11:\"is_verified\";b:1;s:10:\"created_at\";s:10:\"17/09/2026\";s:6:\"images\";a:0:{}s:11:\"admin_reply\";N;s:12:\"masked_phone\";s:10:\"096****899\";}i:11;a:11:{s:8:\"customer\";s:16:\"Bùi Thanh Tùng\";s:2:\"id\";i:25;s:8:\"initials\";s:2:\"TT\";s:13:\"helpful_count\";i:0;s:6:\"rating\";i:5;s:7:\"content\";s:170:\"Bố mình huyết áp cao đang dùng thuốc, hỏi bác sĩ xong uống thêm trà nụ tam thất mỗi sáng. Nói chung hàng sạch, không mốc mọt, yên tâm.\";s:11:\"is_verified\";b:1;s:10:\"created_at\";s:10:\"13/09/2026\";s:6:\"images\";a:0:{}s:11:\"admin_reply\";N;s:12:\"masked_phone\";s:10:\"097****788\";}i:12;a:11:{s:8:\"customer\";s:16:\"Cao Đình Phong\";s:2:\"id\";i:36;s:8:\"initials\";s:3:\"ĐP\";s:13:\"helpful_count\";i:0;s:6:\"rating\";i:5;s:7:\"content\";s:144:\"Trà ngon, đúng chuẩn nụ tam thất loại 1. Mình nhận có vài nụ bị dập nhẹ do vận chuyển, may mà shop đổi bù ngay.\";s:11:\"is_verified\";b:1;s:10:\"created_at\";s:10:\"11/09/2026\";s:6:\"images\";a:0:{}s:11:\"admin_reply\";N;s:12:\"masked_phone\";s:10:\"096****899\";}i:13;a:11:{s:8:\"customer\";s:20:\"Đặng Bảo Ngọc\";s:2:\"id\";i:24;s:8:\"initials\";s:2:\"BN\";s:13:\"helpful_count\";i:0;s:6:\"rating\";i:5;s:7:\"content\";s:178:\"Lần thứ hai mua của Mộc Xanh. Đơn trước mua củ, lần này mua thêm nụ để pha trà hằng ngày cho tiện. Chất lượng đồng đều, đóng gói kỹ.\";s:11:\"is_verified\";b:1;s:10:\"created_at\";s:10:\"09/09/2026\";s:6:\"images\";a:0:{}s:11:\"admin_reply\";N;s:12:\"masked_phone\";s:10:\"091****677\";}i:14;a:11:{s:8:\"customer\";s:15:\"Vũ Đức Long\";s:2:\"id\";i:23;s:8:\"initials\";s:3:\"ĐL\";s:13:\"helpful_count\";i:0;s:6:\"rating\";i:5;s:7:\"content\";s:193:\"Nụ sấy khô chuẩn, bóp thử thấy giòn không ẩm, mùi thảo mộc tự nhiên không hắc. Mình kết hợp nụ tam thất với táo đỏ hãm chung, uống rất hợp vị.\";s:11:\"is_verified\";b:1;s:10:\"created_at\";s:10:\"05/09/2026\";s:6:\"images\";a:0:{}s:11:\"admin_reply\";N;s:12:\"masked_phone\";s:10:\"090****566\";}i:15;a:11:{s:8:\"customer\";s:16:\"Hoàng Thu Trang\";s:2:\"id\";i:22;s:8:\"initials\";s:2:\"TT\";s:13:\"helpful_count\";i:0;s:6:\"rating\";i:5;s:7:\"content\";s:176:\"Dân văn phòng như mình tiện lắm, ủ bình 1L mang đi làm cả ngày. Trà thanh mát, không gắt, chiều đỡ buồn ngủ hẳn. Ship nhanh 2 ngày tới nơi.\";s:11:\"is_verified\";b:1;s:10:\"created_at\";s:10:\"02/09/2026\";s:6:\"images\";a:0:{}s:11:\"admin_reply\";N;s:12:\"masked_phone\";s:10:\"098****033\";}i:16;a:11:{s:8:\"customer\";s:16:\"Phạm Gia Hảo\";s:2:\"id\";i:21;s:8:\"initials\";s:2:\"GH\";s:13:\"helpful_count\";i:0;s:6:\"rating\";i:5;s:7:\"content\";s:180:\"Đặt làm quà biếu bố vợ, bao bì chỉn chu có tem truy xuất nguồn gốc. Bố vợ uống tuần nay khen mất ngủ đỡ hơn nhiều. Sẽ quay lại mua thêm.\";s:11:\"is_verified\";b:1;s:10:\"created_at\";s:10:\"28/08/2026\";s:6:\"images\";a:0:{}s:11:\"admin_reply\";N;s:12:\"masked_phone\";s:10:\"096****455\";}i:17;a:11:{s:8:\"customer\";s:16:\"Lê Minh Tuyết\";s:2:\"id\";i:20;s:8:\"initials\";s:2:\"MT\";s:13:\"helpful_count\";i:0;s:6:\"rating\";i:5;s:7:\"content\";s:178:\"Hãm 5 nụ với nước khoảng 90 độ, để 5 phút, nước trong không đục. Vị dễ uống hơn mình tưởng, có thể hãm lại 2-3 lần nước vẫn thơm.\";s:11:\"is_verified\";b:1;s:10:\"created_at\";s:10:\"24/08/2026\";s:6:\"images\";a:0:{}s:11:\"admin_reply\";N;s:12:\"masked_phone\";s:10:\"093****244\";}i:18;a:11:{s:8:\"customer\";s:19:\"Nguyễn Hoàng Nam\";s:2:\"id\";i:19;s:8:\"initials\";s:2:\"HN\";s:13:\"helpful_count\";i:0;s:6:\"rating\";i:5;s:7:\"content\";s:163:\"Mua 500g pha trà uống mỗi tối, ngủ sâu hơn rõ. Nụ nguyên vẹn gần như 100%, không lẫn cuống già. Shop tư vấn nhiệt tình qua hotline.\";s:11:\"is_verified\";b:1;s:10:\"created_at\";s:10:\"19/08/2026\";s:6:\"images\";a:0:{}s:11:\"admin_reply\";N;s:12:\"masked_phone\";s:10:\"091****866\";}i:19;a:11:{s:8:\"customer\";s:20:\"Trần Thị Kim Anh\";s:2:\"id\";i:18;s:8:\"initials\";s:2:\"KA\";s:13:\"helpful_count\";i:0;s:6:\"rating\";i:5;s:7:\"content\";s:191:\"Nụ tam thất khô đều, không vụn nát, hãm trà nước vàng nhạt hương thảo mộc nhẹ, vị đắng thanh rồi ngọt hậu. Đóng gói túi zip kín có gói hút ẩm.\";s:11:\"is_verified\";b:1;s:10:\"created_at\";s:10:\"16/08/2026\";s:6:\"images\";a:0:{}s:11:\"admin_reply\";N;s:12:\"masked_phone\";s:10:\"090****234\";}}s:5:\"stats\";a:4:{s:3:\"avg\";d:5;s:7:\"average\";d:5;s:5:\"total\";i:20;s:7:\"by_star\";a:5:{i:5;i:19;i:4;i:1;i:3;i:0;i:2;i:0;i:1;i:0;}}}', 1792036159);
INSERT INTO `cache` VALUES ('laravel-cache-review:v1:product_reviews:4', 'a:2:{s:7:\"reviews\";a:20:{i:0;a:11:{s:8:\"customer\";s:9:\"buithilan\";s:2:\"id\";i:112;s:8:\"initials\";s:1:\"B\";s:13:\"helpful_count\";i:0;s:6:\"rating\";i:5;s:7:\"content\";s:68:\"mua lam qua tet ai cung khen. hang chuan loai 1, thom ngot tu nhien.\";s:11:\"is_verified\";b:0;s:10:\"created_at\";s:10:\"13/10/2026\";s:6:\"images\";a:0:{}s:11:\"admin_reply\";N;s:12:\"masked_phone\";s:10:\"092****436\";}i:1;a:11:{s:8:\"customer\";s:17:\"Đặng Thị Hoa\";s:2:\"id\";i:111;s:8:\"initials\";s:2:\"TH\";s:13:\"helpful_count\";i:0;s:6:\"rating\";i:5;s:7:\"content\";s:124:\"Chất lượng tuyệt vời từ bao bì đến sản phẩm bên trong. Táo đỏ ngọt, thịt dày, ăn rất thích.\";s:11:\"is_verified\";b:0;s:10:\"created_at\";s:10:\"12/10/2026\";s:6:\"images\";a:0:{}s:11:\"admin_reply\";N;s:12:\"masked_phone\";s:10:\"091****426\";}i:2;a:11:{s:8:\"customer\";s:13:\"phamhoanglong\";s:2:\"id\";i:110;s:8:\"initials\";s:1:\"P\";s:13:\"helpful_count\";i:0;s:6:\"rating\";i:5;s:7:\"content\";s:68:\"tao ngon, qua to deu, dong goi sach sẽ. rat hai long voi san pham.\";s:11:\"is_verified\";b:0;s:10:\"created_at\";s:10:\"10/10/2026\";s:6:\"images\";a:0:{}s:11:\"admin_reply\";N;s:12:\"masked_phone\";s:10:\"096****509\";}i:3;a:11:{s:8:\"customer\";s:17:\"Phạm Thanh Tâm\";s:2:\"id\";i:109;s:8:\"initials\";s:2:\"TT\";s:13:\"helpful_count\";i:0;s:6:\"rating\";i:5;s:7:\"content\";s:131:\"Mua về nấu chè dưỡng nhan cực kỳ hợp ý. Táo thơm, ngọt đậm đà. Sẽ giới thiệu cho bạn bè cùng mua.\";s:11:\"is_verified\";b:0;s:10:\"created_at\";s:10:\"08/10/2026\";s:6:\"images\";a:0:{}s:11:\"admin_reply\";N;s:12:\"masked_phone\";s:10:\"038****440\";}i:4;a:11:{s:8:\"customer\";s:13:\"nguyenvanhung\";s:2:\"id\";i:108;s:8:\"initials\";s:1:\"N\";s:13:\"helpful_count\";i:0;s:6:\"rating\";i:5;s:7:\"content\";s:70:\"hang chat luong cao, gia ca hop ly. giao hang nhanh chong, nhiet tinh.\";s:11:\"is_verified\";b:0;s:10:\"created_at\";s:10:\"06/10/2026\";s:6:\