INSERT INTO `reviews` VALUES (1, 1, 1, '127.0.0.1', 'Nguyen Thu', NULL, NULL, 5, 'Hương vị rất thơm ngon, đóng gói cẩn thận. Tôi sẽ mua lại lần nữa.', NULL, 1, NULL, 'approved', '2026-10-05 19:12:11', '2026-10-05 19:12:11');
INSERT INTO `reviews` VALUES (2, 1, NULL, '::1', 'Hoàng Chấn', '0352806324', NULL, 5, 'Rất tốt, sản phẩm chuẩn Tây Bắc', NULL, 1, NULL, 'approved', '2026-10-06 07:27:50', '2026-10-06 07:27:50');
INSERT INTO `reviews` VALUES (3, 1, NULL, '113.23.45.101', 'Trần Minh Hải', '0912446127', NULL, 5, 'Củ tam thất khô chuẩn, mặt cắt xám ngọc đúng như mô tả, tán bột uống rất dễ. Giao hàng hơi lâu so với hẹn. Nói chung vẫn sẽ mua lại.', NULL, 1, NULL, 'approved', '2026-08-21 10:09:02', '2026-08-21 10:09:02');
INSERT INTO `reviews` VALUES (4, 1, NULL, '113.23.45.102', 'Nguyễn Thị Lan', '0987654321', NULL, 5, 'Củ già 3-4 năm, cầm nặng tay, gõ nghe tiếng đanh. Thái lát hầm gà ác nước rất ngọt, hậu ngọt sâu ở cổ họng. Đóng gói túi zip kèm gói hút ẩm kỹ càng.', NULL, 1, NULL, 'approved', '2026-10-07 20:27:45', '2026-10-07 20:27:45');
INSERT INTO `reviews` VALUES (5, 1, NULL, '113.23.45.103', 'Lê Văn Cường', '0905112233', NULL, 5, 'Mua về tán bột uống mỗi sáng 3g pha mật ong, người khỏe hơn rõ, ngủ sâu giấc. Shop hỗ trợ tán bột miễn phí nhanh gọn. Rất hài lòng.', NULL, 1, NULL, 'approved', '2026-08-21 10:38:47', '2026-08-21 10:38:47');
INSERT INTO `reviews` VALUES (6, 1, NULL, '113.23.45.104', 'Phạm Thu Hà', '0936778899', NULL, 5, 'Chị đồng nghiệp giới thiệu, đặt thử 500g. Củ đều nhau, không thấy vụn trộn bột lạ, hãm nước uống vị đắng nhẹ rồi ngọt hậu. Sẽ mua thêm làm quà biếu.', NULL, 1, NULL, 'approved', '2026-10-08 02:37:45', '2026-10-08 02:37:45');
INSERT INTO `reviews` VALUES (7, 1, NULL, '113.23.45.105', 'Võ Quốc Bảo', '0913445566', NULL, 5, 'Giá cao hơn ngoài chợ nhưng chất lượng thì khỏi bàn: không mùi hắc sulphur, ruột xám xanh đúng chuẩn tam thất bắc. Có tem truy xuất nguồn gốc, yên tâm.', NULL, 1, NULL, 'approved', '2026-08-22 15:59:30', '2026-08-22 15:59:30');
INSERT INTO `reviews` VALUES (8, 1, NULL, '113.23.45.106', 'Đặng Thị Mai', '0972334455', NULL, 5, 'Sau sinh 6 tháng mình dùng theo hướng dẫn của shop, bổ máu, da dẻ hồng hào hơn. Tư vấn nhiệt tình qua hotline, gửi cả cách dùng chi tiết.', NULL, 1, NULL, 'approved', '2026-10-13 10:51:21', '2026-10-13 10:51:21');
INSERT INTO `reviews` VALUES (9, 1, NULL, '113.23.45.107', 'Bùi Đức Toàn', '0903556677', NULL, 5, 'Mua 1kg loại 24-26 củ/kg ngâm rượu hạ thổ. Củ to đẹp đồng đều, không sâu mọt. Giao hàng đóng thùng carton chống sốc cẩn thận.', NULL, 1, NULL, 'approved', '2026-09-14 17:05:21', '2026-09-14 17:05:21');
INSERT INTO `reviews` VALUES (10, 1, NULL, '113.23.45.108', 'Hoàng Thị Nhung', '0918223344', NULL, 5, 'Nhà có người tai biến nên tôi mua về cho uống cùng thuốc theo chỉ định bác sĩ. Hàng chuẩn, không lẫn tam thất nam, vị đắng đặc trưng rõ rệt.', NULL, 1, NULL, 'approved', '2026-09-20 15:39:45', '2026-09-20 15:39:45');
INSERT INTO `reviews` VALUES (11, 1, NULL, '113.23.45.109', 'Ngô Văn Sơn', '0968112233', NULL, 5, 'Lần thứ 3 đặt hàng. Bột tán mịn, hũ thủy tinh kín, để ngăn mát dùng dần. Ship nhanh, được freeship vì đơn trên 300k. Điểm 5 sao xứng đáng.', NULL, 1, NULL, 'approved', '2026-09-14 13:49:49', '2026-09-14 13:49:49');
INSERT INTO `reviews` VALUES (12, 1, NULL, '113.23.45.110', 'Lưu Thanh Trúc', '0939887766', NULL, 5, 'Thái lát ngâm mật ong 25 ngày đã dùng được, vị dễ uống, cả nhà đều thích. Đóng gói có túi hút ẩm và hướng dẫn bảo quản in rõ ràng.', NULL, 1, NULL, 'approved', '2026-09-27 08:56:54', '2026-09-27 08:56:54');
INSERT INTO `reviews` VALUES (18, 2, NULL, '113.23.45.121', 'Trần Thị Kim Anh', '0905771234', NULL, 5, 'Nụ tam thất khô đều, không vụn nát, hãm trà nước vàng nhạt hương thảo mộc nhẹ, vị đắng thanh rồi ngọt hậu. Đóng gói túi zip kín có gói hút ẩm.', NULL, 1, NULL, 'approved', '2026-08-16 09:23:41', '2026-08-16 09:23:41');
INSERT INTO `reviews` VALUES (19, 2, NULL, '113.23.45.122', 'Nguyễn Hoàng Nam', '0912448866', NULL, 5, 'Mua 500g pha trà uống mỗi tối, ngủ sâu hơn rõ. Nụ nguyên vẹn gần như 100%, không lẫn cuống già. Shop tư vấn nhiệt tình qua hotline.', NULL, 1, NULL, 'approved', '2026-08-19 20:14:07', '2026-08-19 20:14:07');
INSERT INTO `reviews` VALUES (20, 2, NULL, '113.23.45.123', 'Lê Minh Tuyết', '0938112244', NULL, 5, 'Hãm 5 nụ với nước khoảng 90 độ, để 5 phút, nước trong không đục. Vị dễ uống hơn mình tưởng, có thể hãm lại 2-3 lần nước vẫn thơm.', NULL, 1, NULL, 'approved', '2026-08-24 14:37:52', '2026-08-24 14:37:52');
INSERT INTO `reviews` VALUES (21, 2, NULL, '113.23.45.124', 'Phạm Gia Hảo', '0967334455', NULL, 5, 'Đặt làm quà biếu bố vợ, bao bì chỉn chu có tem truy xuất nguồn gốc. Bố vợ uống tuần nay khen mất ngủ đỡ hơn nhiều. Sẽ quay lại mua thêm.', NULL, 1, NULL, 'approved', '2026-08-28 08:51:19', '2026-08-28 08:51:19');
INSERT INTO `reviews` VALUES (22, 2, NULL, '113.23.45.125', 'Hoàng Thu Trang', '0981220033', NULL, 5, 'Dân văn phòng như mình tiện lắm, ủ bình 1L mang đi làm cả ngày. Trà thanh mát, không gắt, chiều đỡ buồn ngủ hẳn. Ship nhanh 2 ngày tới nơi.', NULL, 1, NULL, 'approved', '2026-09-02 16:08:33', '2026-09-02 16:08:33');
INSERT INTO `reviews` VALUES (23, 2, NULL, '113.23.45.126', 'Vũ Đức Long', '0903445566', NULL, 5, 'Nụ sấy khô chuẩn, bóp thử thấy giòn không ẩm, mùi thảo mộc tự nhiên không hắc. Mình kết hợp nụ tam thất với táo đỏ hãm chung, uống rất hợp vị.', NULL, 1, NULL, 'approved', '2026-09-05 11:42:58', '2026-09-05 11:42:58');
INSERT INTO `reviews` VALUES (24, 2, NULL, '113.23.45.127', 'Đặng Bảo Ngọc', '0914556677', NULL, 5, 'Lần thứ hai mua của Mộc Xanh. Đơn trước mua củ, lần này mua thêm nụ để pha trà hằng ngày cho tiện. Chất lượng đồng đều, đóng gói kỹ.', NULL, 1, NULL, 'approved', '2026-09-09 19:26:14', '2026-09-09 19:26:14');
INSERT INTO `reviews` VALUES (25, 2, NULL, '113.23.45.128', 'Bùi Thanh Tùng', '0975667788', NULL, 5, 'Bố mình huyết áp cao đang dùng thuốc, hỏi bác sĩ xong uống thêm trà nụ tam thất mỗi sáng. Nói chung hàng sạch, không mốc mọt, yên tâm.', NULL, 1, NULL, 'approved', '2026-09-13 07:55:02', '2026-09-13 07:55:02');
INSERT INTO `reviews` VALUES (26, 2, NULL, '113.23.45.129', 'Ngô Thị Hải Yến', '0968778899', NULL, 5, 'So với chỗ cũ mình từng mua thì nụ ở đây đều và đẹp hơn hẳn, ít nụ nở gãy. Pha ra nước màu vàng óng rất đẹp. Được freeship vì đơn trên 300k.', NULL, 1, NULL, 'approved', '2026-09-17 15:19:46', '2026-09-17 15:19:46');
INSERT INTO `reviews` VALUES (27, 2, NULL, '113.23.45.130', 'Lưu Quang Vũ', '0939889900', NULL, 5, 'Mình mua combo nụ + củ tam thất. Nụ hãm trà, củ tán bột uống riêng. Shop gói kèm hướng dẫn sử dụng in rõ ràng, tỉ mỉ chu đáo.', NULL, 1, NULL, 'approved', '2026-09-21 10:33:27', '2026-09-21 10:33:27');
INSERT INTO `reviews` VALUES (28, 2, NULL, '113.23.45.131', 'Trịnh Thị Lan Phương', '0906990011', NULL, 5, 'Sau sinh 8 tháng mình uống trà nụ tam thất theo hướng dẫn của shop, người ấm áp hơn, sữa cũng đều hơn. Vị hơi đắng đầu lưỡi nhưng hậu ngọt.', NULL, 1, NULL, 'approved', '2026-09-25 21:47:55', '2026-09-25 21:47:55');
INSERT INTO `reviews` VALUES (29, 2, NULL, '113.23.45.132', 'Đỗ Hoài Thương', '0917101122', NULL, 5, 'Nhân viên trực đêm nên mua về pha trà thay cà phê. Tỉnh táo mà không bị hồi hộp, sáng ngủ lại dễ. Nụ khô sạch, không thấy bụi hay vụn lạ.', NULL, 1, NULL, 'approved', '2026-09-29 13:05:38', '2026-09-29 13:05:38');
INSERT INTO `reviews` VALUES (30, 2, NULL, '113.23.45.133', 'Hồ Văn Đạt', '0982212233', NULL, 5, 'Kiểm hàng trước khi thanh toán, mở ra xem kỹ: nụ tím xám tự nhiên đúng mô tả, không non ép. 500g dùng được hơn tháng cho 2 vợ chồng.', NULL, 1, NULL, 'approved', '2026-10-02 18:29:11', '2026-10-02 18:29:11');
INSERT INTO `reviews` VALUES (31, 2, NULL, '113.23.45.134', 'Dương Mỹ Linh', '0963323344', NULL, 5, 'Mùa hanh khô pha nụ tam thất với mật ong uống rất dễ chịu, họng bớt khô. Giá nhỉnh hơn trà thường nhưng chất lượng xứng đáng, sẽ mua lại.', NULL, 1, NULL, 'approved', '2026-10-06 09:58:24', '2026-10-06 09:58:24');
INSERT INTO `reviews` VALUES (32, 2, NULL, '113.23.45.135', 'Phan Nhật Hào', '0904434455', NULL, 5, 'Giao hàng đóng thùng chống sốc cẩn thận, hạn đóng gói in rõ trên bao bì. Trà hãm xong để nguội uống giải khát mùa nóng cũng rất ổn.', NULL, 1, NULL, 'approved', '2026-10-09 16:41:03', '2026-10-09 16:41:03');
INSERT INTO `reviews` VALUES (33, 2, NULL, '113.23.45.136', 'Tô Ánh Tuyết', '0915545566', NULL, 5, 'Mẹ mình 62 tuổi uống đều mỗi tối, bảo giấc ngủ cải thiện, đêm trở dậy ít hơn. Nụ to đều, không lẫn tạp chất. Cảm ơn shop nhiều.', NULL, 1, NULL, 'approved', '2026-10-11 20:12:49', '2026-10-11 20:12:49');
INSERT INTO `reviews` VALUES (34, 2, NULL, '113.23.45.137', 'Vương Tuấn Kiệt', '0976656677', NULL, 5, 'Đặt hôm qua hôm nay đã nhận hàng, đóng gói 2 lớp túi zip. Pha thử tách đầu tiên: hương dịu, vị đắng nhẹ tan nhanh, ngọt hậu kéo dài. Chuẩn bài.', NULL, 1, NULL, 'approved', '2026-10-13 08:26:57', '2026-10-13 08:26:57');
INSERT INTO `reviews` VALUES (35, 2, NULL, '113.23.45.138', 'Mai Thị Hồng Nhung', '0937767788', NULL, 5, 'Khách khó tính như mình cũng phải khen: nụ nguyên bông không dập nát, nước trà trong, không cặn. Đã giới thiệu cho hai chị đồng nghiệp cùng đặt.', NULL, 1, NULL, 'approved', '2026-10-14 10:03:31', '2026-10-14 10:03:31');
INSERT INTO `reviews` VALUES (36, 2, NULL, '113.23.45.139', 'Cao Đình Phong', '0968878899', NULL, 5, 'Trà ngon, đúng chuẩn nụ tam thất loại 1. Mình nhận có vài nụ bị dập nhẹ do vận chuyển, may mà shop đổi bù ngay.', NULL, 1, NULL, 'approved', '2026-09-11 17:34:20', '2026-09-11 17:34:20');
INSERT INTO `reviews` VALUES (37, 2, NULL, '113.23.45.140', 'Mai Hoa', '0989989900', NULL, 4, 'Chất lượng tốt, hậu ngọt rõ.', NULL, 1, NULL, 'approved', '2026-10-04 12:58:44', '2026-10-04 12:58:44');
